import { z } from "zod";

// ── MCP API usage logging v2 (per-key request accounting) ───────────────────
const __MCP_USAGE_LOG_V2__ = true;
import { appendFileSync as __mcpAppend, mkdirSync as __mcpMkdir } from "node:fs";
function __mcpLogApiCall(service, key, url, status, durationMs, errorName) {
    try {
        const dir = process.env.MCP_USAGE_LOG_DIR || "mcp_usage_log";
        const parsed = new URL(url);
        const keyText = String(key || "").replace(/^Bearer\s+/i, "");
        const suffix = keyText ? keyText.slice(-8) : "no-key";
        const now = new Date();
        const month = now.toISOString().slice(0, 7);
        const day = now.toISOString().slice(0, 10).replace(/-/g, "");
        const outDir = dir + "/" + month;
        __mcpMkdir(outDir, { recursive: true });
        __mcpAppend(
            outDir + "/" + service + "_" + suffix + "_" + day + ".jsonl",
            JSON.stringify({
                ts: now.toISOString(), service, key_suffix: suffix,
                host: parsed.hostname, path: parsed.pathname,
                status: status || 0, duration_ms: durationMs,
                error: errorName || null,
                task_id: process.env.MCP_TASK_ID || null,
            }) + "\n"
        );
    } catch (logError) {
        process.stderr.write(`[mcp-usage-log] ${logError?.message || logError}\n`);
    }
}


import axios from "axios";
import { toolRegistry, API_CONFIG } from "./config.js";
import { createRequestLogger } from "../utils/logger.js";
// Register the web search tool
toolRegistry["web_search_exa"] = {
    name: "web_search_exa",
    description: "Search the web using Exa AI - performs real-time web searches and can scrape content from specific URLs. Supports configurable result counts and returns the content from the most relevant websites.",
    schema: {
        query: z.string().describe("Search query"),
        numResults: z.number().optional().describe("Number of search results to return (default: 5)")
    },
    handler: async ({ query, numResults }, extra) => {
        const requestId = `web_search_exa-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`;
        const logger = createRequestLogger(requestId, 'web_search_exa');
        logger.start(query);
        try {
            // Create a fresh axios instance for each request
            const axiosInstance = axios.create({
                baseURL: API_CONFIG.BASE_URL,
                headers: {
                    'accept': 'application/json',
                    'content-type': 'application/json',
                    'Authorization': 'Bearer ' + process.env.EXA_API_KEY || ''
                },
                timeout: 25000
            });
            const searchRequest = {
                query,
                type: "auto",
                numResults: numResults || API_CONFIG.DEFAULT_NUM_RESULTS,
                contents: {
                    text: {
                        maxCharacters: API_CONFIG.DEFAULT_MAX_CHARACTERS
                    },
                    livecrawl: 'always'
                }
            };
            logger.log("Sending request to Exa API");
            let response;
            const __mcpStartedAt = Date.now();
            let __mcpStatus = 0;
            let __mcpError = null;
            const __mcpUrl = API_CONFIG.BASE_URL.replace(/\/$/, "") + "/" +
                API_CONFIG.ENDPOINTS.SEARCH.replace(/^\//, "");
            try {
                response = await axiosInstance.post(API_CONFIG.ENDPOINTS.SEARCH, searchRequest, { timeout: 25000 });
                __mcpStatus = response.status;
            } catch (__mcpExc) {
                __mcpStatus = __mcpExc?.response?.status || 0;
                __mcpError = __mcpExc?.name || "Error";
                throw __mcpExc;
            } finally {
                __mcpLogApiCall(
                    "exa", process.env.EXA_API_KEY || "", __mcpUrl,
                    __mcpStatus, Date.now() - __mcpStartedAt, __mcpError
                );
            }
            logger.log("Received response from Exa API");
            if (!response.data || !response.data.results) {
                logger.log("Warning: Empty or invalid response from Exa API");
                return {
                    content: [{
                            type: "text",
                            text: "No search results found. Please try a different query."
                        }]
                };
            }
            logger.log(`Found ${response.data.results.length} results`);
            const result = {
                content: [{
                        type: "text",
                        text: JSON.stringify(response.data, null, 2)
                    }]
            };
            logger.complete();
            return result;
        }
        catch (error) {
            logger.error(error);
            if (axios.isAxiosError(error)) {
                // Handle Axios errors specifically
                const statusCode = error.response?.status || 'unknown';
                const errorMessage = error.response?.data?.message || error.message;
                logger.log(`Axios error (${statusCode}): ${errorMessage}`);
                return {
                    content: [{
                            type: "text",
                            text: `Search error (${statusCode}): ${errorMessage}`
                        }],
                    isError: true,
                };
            }
            // Handle generic errors
            return {
                content: [{
                        type: "text",
                        text: `Search error: ${error instanceof Error ? error.message : String(error)}`
                    }],
                isError: true,
            };
        }
    },
    enabled: true // Enabled by default
};
